	let u = w * w * ( 3.0 - 2.0 * w ); let du = 6.0 * w * ( 1.0 - w );
	let a = skHash( i ); let b = skHash( i + vec3i( 1, 0, 0 ) ); let c = skHash( i + vec3i( 0, 1, 0 ) ); let d = skHash( i + vec3i( 1, 1, 0 ) );
	let e = skHash( i + vec3i( 0, 0, 1 ) ); let ff = skHash( i + vec3i( 1, 0, 1 ) ); let g = skHash( i + vec3i( 0, 1, 1 ) ); let h = skHash( i + vec3i( 1, 1, 1 ) );
	let k1 = b - a; let k2 = c - a; let k3 = e - a; let k4 = a - b - c + d; let k5 = a - c - e + g; let k6 = a - b - e + ff; let k7 = - a + b + c - d + e - ff - g + h;
