`,surface:`
	let reg = i32( in.vs.vReg );
	let op = in.vs.vOff;
	let ex = in.vs.vEx;
	let occ = sat( in.vs.vRig.w );
	let sAlong = in.vs.vRig.y * mat.chainInfo[ u32( in.vs.vRig.x + 0.5 ) ].z;
	let pat = i32( mat.look.x + 0.5 );
	let psz = mat.look.y;
	let rad = max( length( op.xy ), 1e-3 );
	// pattern coordinates on the body surface: along the chain and round it (arc length)
	let around = atan2( op.x, op.y );
	let arc = around * rad;
	// the footprint of a pixel on the body: fine relief and pattern contrast fade with it (no shimmer)
