	let fine = 1.0 - smoothstep( psz * 0.015, psz * 0.07, px );
	let mid = 1.0 - smoothstep( psz * 0.06, psz * 0.35, px );
	var col = mat.cDorsal;
	var rough = mat.look.z;
	var metal = 0.0;
	var emis = vec3f( 0.0 );
	var cc = 0.25 * mat.look2.w;
	var ccRough = 0.16;
