			let ln = abs( fract( ( sAlong * 0.8 + arc * 0.6 ) / ( psz * 0.7 ) + mNoise( vec3f( sAlong * 0.6 / psz, arc * 0.6 / psz, 33.0 ) ) * 0.35 ) - 0.5 );
			let rake = ( 1.0 - smoothstep( 0.0, 0.03, ln ) ) * zone;
