			let gi = floor( g );
			let hh = mHash( vec3f( gi, 37.0 ) );
			let cc2 = gi + 0.5 + ( vec2f( hh, mHash( vec3f( gi, 39.0 ) ) ) - 0.5 ) * 0.4;
