		let g = normalize( vec3f( in.vs.vEye.x, in.vs.vEye.y, 1.0 ) );
		let t1 = normalize( cross( vec3f( 0.0, 1.0, 0.0 ), g ) );
		let t2 = cross( g, t1 );
		let q2 = vec2f( dot( d, t1 ), dot( d, t2 ) );
		let front = step( 0.0, dot( d, g ) );
		let r = length( q2 );
		let iR = mat.look2.y;
		let iris = ( 1.0 - smoothstep( iR - 0.04, iR + 0.01, r ) ) * front;
		let pt = i32( mat.look2.x + 0.5 );
