	let scan = in.vs.vCol;
	if ( scan.a > 0.0 ) { col *= mix( vec3f( 1.0 ), scan.rgb, scan.a * mat.look4.w ); }
	// occlusion baked per vertex (mouth, sockets, creases, arm roots): darkens the ambient and some direct
	s.ao = 1.0 - occ;
	col *= 1.0 - 0.5 * occ;
