	cc = max( cc, rec.y * mix( 0.3, 0.75, film ) * mat.look2.w ) * ( 1.0 - occ * 0.6 );
	rough = mix( rough, rough * 1.25, 1.0 - film ) ;
	col = mix( col, vec3f( 1.0, 0.25, 0.15 ), rec.x * 0.55 );
